package com.nigson.acceptance.carrier;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.acceptance.files.StorageFixture;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import static org.assertj.core.api.Assertions.*;
/** Actual owner PostgreSQL and private PDF proof; source cancellation does not touch stock or payments. */
class CarrierCancellationPersistenceTest {
 ShipmentFixture f;StorageFixture storage;JdbcTemplate jdbc;CarrierCancellationService service;FulfillmentValues.Shipment shipment;org.springframework.transaction.PlatformTransactionManager manager;
 @BeforeEach void setup()throws Exception{String url=System.getenv("NIGSON_TEST_JDBC_URL"),fixture=System.getenv("NIGSON_TEST_CARRIER_STORAGE_FIXTURE");Assumptions.assumeTrue(url!=null&&fixture!=null,"native database and TLS storage required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);f=new ShipmentFixture(jdbc,manager);CarrierContextPersistenceTest.freeze(f);shipment=f.create("5","FEDEX",null,"cancel-intent");CarrierReconciliationPersistenceTest.ngMarket(f);storage=new StorageFixture(fixture);var clock=Clock.systemUTC();var policy=new FulfillmentPolicy(true,"test","MOCK","SYNTHETIC_OFFLINE",Instant.now().plusSeconds(3600),"",Set.of("tracking.synthetic.invalid"),clock,"1".repeat(64));var commands=new PlatformStore(jdbc,manager,clock,f.metrics);var audit=new AuditWriter(jdbc,clock,f.metrics);service=new CarrierCancellationService(jdbc,f.repository,new InventoryAuthority(jdbc),commands,audit,policy,manager,clock);var booked=CarrierResultPersistenceTest.putLabel(storage,shipment.id(),UUID.randomUUID(),booking().toString());shipment=new CarrierResultService(jdbc,f.repository,storage.storage,policy,commands,audit,manager,clock,"test",f.metrics).accept(CarrierResultPersistenceTest.proof(),shipment.id(),booked,UUID.randomUUID());}
 @AfterEach void cleanup(){if(f!=null)f.close();if(storage!=null)storage.close();}
 UUID booking(){return jdbc.queryForObject("SELECT booking_request_id FROM commerce.shipment WHERE id=?",UUID.class,shipment.id());}
 CarrierCancellationValues.View request(String key){return service.request(f.inventory.actor,shipment.id(),shipment.version(),"Synthetic carrier cancellation request",key,UUID.randomUUID());}
 PrivateWorkload.Proof proof(){return new PrivateWorkload.Proof("nigson-integration","synthetic-cancellation",PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-199")).findFirst().orElseThrow(),null);}
 CarrierCancellationValues.Receipt receipt(UUID id,String state){return new CarrierCancellationValues.Receipt(UUID.randomUUID(),id,shipment.id(),booking(),"123456789012","MOCK",state,Instant.now(),state.equals("CANCELLED")?"NONE":state.equals("REJECTED")?"CARRIER_CANCEL_REJECTED":"PROVIDER_OUTCOME_UNKNOWN");}
 void dispatch(){f.service.dispatch(f.inventory.actor,shipment.id(),shipment.version(),"Synthetic actual physical handover","dispatch",UUID.randomUUID());}
 @Test void activeIntentAndUnknownExcludeDispatchWhileCancelledNeverChangesStockOrMoney(){var intent=request("cancel");assertThat(intent.state()).isEqualTo("REQUESTED");assertThatThrownBy(this::dispatch).hasMessage("FULFILLMENT_RULE_VIOLATION");service.accept(proof(),receipt(intent.id(),"UNKNOWN"),UUID.randomUUID());assertThatThrownBy(this::dispatch).hasMessage("FULFILLMENT_RULE_VIOLATION");var result=receipt(intent.id(),"CANCELLED");assertThat(service.accept(proof(),result,UUID.randomUUID()).state()).isEqualTo("CANCELLED");assertThat(service.accept(proof(),result,UUID.randomUUID()).state()).isEqualTo("CANCELLED");assertThat(service.accept(proof(),receipt(intent.id(),"UNKNOWN"),UUID.randomUUID()).state()).isEqualTo("CANCELLED");assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("CANCELLED");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");assertThat(jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.shipment_event WHERE shipment_id=? AND status='CANCELLED'",Integer.class,shipment.id())).isEqualTo(1);assertThat(request("cancel").state()).isEqualTo("CANCELLED");}
 @Test void knownRejectionReleasesDispatchHold(){var intent=request("rejected");assertThat(service.accept(proof(),receipt(intent.id(),"REJECTED"),UUID.randomUUID()).state()).isEqualTo("REJECTED");dispatch();assertThat(f.value("on_hand")).isEqualByComparingTo("5");assertThat(f.value("allocated")).isZero();}
 @Test void dispatchFirstRejectsCancellationWithoutCreatingIntent(){dispatch();assertThatThrownBy(()->service.request(f.inventory.actor,shipment.id(),shipment.version()+1,"Synthetic cancellation after handover","late",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.carrier_cancellation WHERE shipment_id=?",Integer.class,shipment.id())).isZero();}
 @Test void auditFailureRollsBackIntentAndCancellationTruth(){f.inventory.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->request("audit")).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{f.inventory.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.carrier_cancellation WHERE shipment_id=?",Integer.class,shipment.id())).isZero();var intent=request("audit");var result=receipt(intent.id(),"CANCELLED");f.inventory.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->service.accept(proof(),result,UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{f.inventory.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("READY");assertThat(service.accept(proof(),result,UUID.randomUUID()).state()).isEqualTo("CANCELLED");}
 @Test void originalBusinessIntentDeduplicatesAcrossKeysAndRequiresCurrentAuthority(){var first=request("one");assertThat(request("two").id()).isEqualTo(first.id());var actor=f.inventory.actor;var stale=new ActorAssertion.Actor(actor.party(),actor.identityIssuer(),actor.identitySubject(),null,actor.roles(),actor.scopes(),Instant.now().minusSeconds(901));assertThatThrownBy(()->service.request(stale,shipment.id(),shipment.version(),"Synthetic stale operator request","one",UUID.randomUUID())).hasMessage("ACTOR_TRUST_REJECTED");jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",actor.party());assertThatThrownBy(()->request("one")).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->service.get(actor,shipment.id())).hasMessage("ACCESS_DENIED");}
 @Test void callbackCannotCancelPhysicalDispatchOrForeignIdentity(){var intent=request("binding");var wrong=new CarrierCancellationValues.Receipt(UUID.randomUUID(),intent.id(),shipment.id(),UUID.randomUUID(),"123456789012","MOCK","CANCELLED",Instant.now(),"NONE");assertThatThrownBy(()->service.accept(proof(),wrong,UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");service.accept(proof(),receipt(intent.id(),"REJECTED"),UUID.randomUUID());dispatch();assertThatThrownBy(()->service.accept(proof(),receipt(intent.id(),"CANCELLED"),UUID.randomUUID())).hasMessage("INVALID_TRANSITION");assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("SHIPPED");}
 @Test void populatedCancellationRollbackRefusesBeforeDroppingEvidence()throws Exception{var intent=request("rollback");String ddl=java.nio.file.Files.readString(java.nio.file.Path.of(System.getenv("NIGSON_EVENT_FIXTURES")).getParent().getParent().getParent().resolve("services/commerce/src/main/resources/db/changelog/025-bp1-carrier-cancellation-rollback.sql"));assertThatThrownBy(()->f.inventory.admin.execute(ddl)).hasMessageContaining("Populated table commerce.carrier_cancellation");assertThat(service.get(f.inventory.actor,shipment.id()).id()).isEqualTo(intent.id());}
 @Test void cancellationAndPhysicalDispatchRaceUnderOneSourceLockOrder()throws Exception{var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var cancel=pool.submit(()->{start.await();try{return request("race")!=null;}catch(com.nigson.shared.problem.Problem.Failure denied){assertThat(denied.getMessage()).isIn("FULFILLMENT_RULE_VIOLATION","VERSION_MISMATCH");return false;}});var dispatch=pool.submit(()->{start.await();try{dispatch();return true;}catch(com.nigson.shared.problem.Problem.Failure denied){assertThat(denied.getMessage()).isIn("FULFILLMENT_RULE_VIOLATION","VERSION_MISMATCH");return false;}});start.countDown();boolean cancelled=cancel.get(15,TimeUnit.SECONDS),shipped=dispatch.get(15,TimeUnit.SECONDS);assertThat(cancelled^shipped).isTrue();assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo(shipped?"SHIPPED":"READY");assertThat(f.value("on_hand")).isEqualByComparingTo(shipped?"5":"10");}}
 @Test void relayReplaysOriginalRequestAfterLostAcceptanceAndRecoversSavedResult()throws Exception{var intent=request("relay");var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);var calls=new java.util.concurrent.atomic.AtomicInteger();var wire=new java.util.concurrent.atomic.AtomicReference<String>();var violation=new java.util.concurrent.atomic.AtomicReference<Throwable>();var saved=receipt(intent.id(),"CANCELLED");server.createContext("/internal/v1/carrier/cancellations",exchange->{try{String body=new String(exchange.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);String prior=wire.getAndSet(body);if(prior!=null)assertThat(body).isEqualTo(prior);assertThat(exchange.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer synthetic-workload");assertThat(exchange.getRequestHeaders().getFirst("Idempotency-Key")).isEqualTo(intent.id().toString());assertThat(exchange.getRequestHeaders().getFirst("X-Nigson-Actor")).isNull();f.inventory.tx.executeWithoutResult(t->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.queryForMap("SELECT id FROM commerce.shipment WHERE id=? FOR UPDATE",shipment.id());jdbc.queryForMap("SELECT id FROM commerce.carrier_cancellation WHERE id=? FOR UPDATE",intent.id());});if(calls.incrementAndGet()==1){exchange.sendResponseHeaders(202,100);exchange.getResponseBody().write('{');exchange.close();return;}byte[] response=com.nigson.shared.events.EventCodec.JSON.writeValueAsBytes(Map.of("cancellationId",intent.id(),"shipmentId",shipment.id(),"state","CANCELLED","receipt",saved));exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(202,response.length);exchange.getResponseBody().write(response);exchange.close();}catch(Throwable failure){violation.set(failure);exchange.close();}});server.start();try{var relay=new CarrierCancellationRelay(jdbc,manager,new HttpCarrierCancellation("test","http://127.0.0.1:"+server.getAddress().getPort(),route->{assertThat(route.scope()).isEqualTo("carrier.cancel");return "synthetic-workload";}),service,new AuditWriter(jdbc,Clock.systemUTC(),f.metrics),Clock.systemUTC());relay.poll();assertThat(service.get(f.inventory.actor,shipment.id()).state()).isEqualTo("UNKNOWN");assertThatThrownBy(this::dispatch).hasMessage("FULFILLMENT_RULE_VIOLATION");jdbc.update("UPDATE commerce.carrier_cancellation SET next_attempt_at=now() WHERE id=?",intent.id());relay.poll();assertThat(service.get(f.inventory.actor,shipment.id()).state()).isEqualTo("CANCELLED");assertThat(service.accept(proof(),saved,UUID.randomUUID()).state()).isEqualTo("CANCELLED");assertThat(calls.get()).isEqualTo(2);assertThat(violation.get()).isNull();}finally{server.stop(0);}}

}
